---@param cs_list System.Collections.Generic.List
local function list_ipairs(cs_list)
    local index = -1
    return function(...)
        index = index + 1
        if index < cs_list.Count then
            return index, cs_list[index]
        end
    end
end

-- cs字典迭代器
---@param cs_enumerator any
---@return any, any
local function dictionary_iter(cs_enumerator)
    if cs_enumerator:MoveNext() then
        local current = cs_enumerator.Current
        return current.Key, current.Value
    end
end

---@param cs_idictionary System.Collections.Generic.Dictionary
---@return any, any
local function dictionary_ipairs(cs_idictionary)
    local cs_enumerator = cs_idictionary:GetEnumerator()
    return dictionary_iter, cs_enumerator
end

